-- vendor network: every 527 (whole Schedule B) paying the 19's top vendors; second field = payee state must be one the 19 saw for that vendor. copies across forms dropped.
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
b AS (SELECT EIN, ORG_NAME, REGEXP_REPLACE(REGEXP_REPLACE(UPPER(RECIPIENT_NAME),'[^A-Z0-9]',''),'(LLC|INC|CORP|CORPORATION|CO|LTD|LP)$','') v, UPPER(TRIM(RECIPIENT_STATE)) st,
   EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES),
vend AS (SELECT v, ARRAY_AGG(DISTINCT st) sts FROM b WHERE EIN IN (SELECT EIN FROM g) AND v IN ('RESIDENTIALPROGRAMS','BFTELECOM','CAMPAIGNCALLING','AMERICANLIBERTYGROUP','SIMPLEDATA','UNITEDSUPPORT','ONEVOICESOLUTIONS',
  'NORTHAMERICANFULFILLMENT','NORTHAMERICANFULFILMENT','POLITICALRESPONSE','GSI','PROSPEAKING','OPTICALMARKETING','PUBLICSUPPORTSERVICES','GRASSROOTSFUNDGROUP','POLITICALFUNDRAISINGGROUP','CAPITALVENDORMANAGEMENT',
  'POLITICALMARKETINGSERVICES','EMERGENTMARKETING','ACTIONCOMMITTEEMARKETING','UNIQTECHNOLOGIES','VENDORSYSTEMS','THEFUNDRAISINGGROUP','ADVANCEDCREATIVEMEDIA','GCI','CAMPAIGNMARKETING','AMERICANMARKETINGSERVICES') GROUP BY v),
f AS (SELECT b.EIN, b.v, b.d, b.a, b.FORM_ID_NUMBER, COUNT(*) n, ANY_VALUE(ORG_NAME) org FROM b JOIN vend ON vend.v=b.v AND ARRAY_CONTAINS(b.st::variant, vend.sts) GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, v, d, a, MAX(n) n, ANY_VALUE(org) org FROM f GROUP BY 1,2,3,4)
SELECT EIN, MAX(org) org, IFF(EIN IN (SELECT EIN FROM g),'Y','N') in19, v, ROUND(SUM(n*a)/1e6,3) amt_m, MIN(d) first_d, MAX(d) last_d, COUNT(*) pay_rows
FROM k GROUP BY EIN, v ORDER BY in19, v, amt_m DESC
